#ifndef SHANKPIT_AMBIENT_LIFE_H
#define SHANKPIT_AMBIENT_LIFE_H

/* ambient_life.h -- what an NPC says when nothing is happening, in SHANKPIT.
 *
 * Founder real-time (2026-10-30): "NOOBTOPIA is the data for making our world seem more alive we script in more
 * random interactions like the talking from noobtopia" / "PARENA IS THE GL[UE]".
 *
 * The three-way split, made concrete:
 *   * the DECISIONS (which kind of line, how long until it may speak, which line) are PARENA's, once:
 *     stdlib/noobtopia/ambient_life.prn -> packages/simulation/ambient_life.c (generated, do not edit);
 *   * the WORDS are NOOBTOPIA's, once: NOOBTOPIA/data/noob_lines.lua -> packages/simulation/ambient_lines.inc
 *     (generated by scripts/gen_ambient_lines.sh, do not edit);
 *   * this file is the thin host that joins them and hands a caller a string.
 *
 * It is header-only and stateless: the caller passes its own seed, so a server and every client can run the same
 * code and get the same answer. See MONOREPO/docs/THREE_WAY_MERGE.md.
 */

/* PARENA-generated (packages/simulation/ambient_life.c). */
int ambient_category_count(void);
int ambient_category_for_mood(int mood);
int ambient_cooldown_ms(int mood, int seed);
int ambient_should_speak(int mood, int since_ms, int seed);
int ambient_pick(int count, int seed);

typedef struct { int category; const char *text; } AmbientLine;

/* Generated from NOOBTOPIA's data file: defines g_ambient_lines[] and g_ambient_line_count. */
#include "ambient_lines.inc"

/* The same deterministic generator NOOBTOPIA's Luau side uses, so a seed means the same thing in both worlds. */
static inline unsigned int ambient_life_next_seed(unsigned int seed) {
    return (seed * 1103515245u + 12345u) & 0x7FFFFFFFu;
}

static inline int ambient_life_count_in(int category) {
    int n = 0;
    for (int i = 0; i < g_ambient_line_count; i++)
        if (g_ambient_lines[i].category == category) n++;
    return n;
}

/* The whole decision: given an NPC's mood and how long it has been quiet, either a line to say or NULL.
 * `*seed` is advanced only when a line is actually chosen, which is what makes a caller's own RNG stream stable
 * whether or not an NPC happens to speak on a given tick. */
static inline const char *ambient_life_speak(int mood, int since_ms, unsigned int *seed) {
    if (!seed) return 0;
    if (ambient_should_speak(mood, since_ms, (int)(*seed & 0x7FFFFFFF)) != 1) return 0;
    int cat = ambient_category_for_mood(mood);
    int count = ambient_life_count_in(cat);
    if (count <= 0) {                       /* a category nobody wrote lines for must not silence the NPC */
        cat = 0;
        count = ambient_life_count_in(cat);
        if (count <= 0) return 0;
    }
    *seed = ambient_life_next_seed(*seed);
    int want = ambient_pick(count, (int)(*seed & 0x7FFFFFFF));
    for (int i = 0; i < g_ambient_line_count; i++) {
        if (g_ambient_lines[i].category != cat) continue;
        if (want-- == 0) return g_ambient_lines[i].text;
    }
    return 0;
}

#endif
